import "server-only";
import { headers } from "next/headers";
import { PRICE_CONFIG } from "@/lib/pricing";

export type PriceSearchParams = Promise<{
  country?: string | string[];
}>;

export async function localizedPrice(searchParams: PriceSearchParams) {
  const requestHeaders = await headers();
  const countryHeader =
    requestHeaders.get("x-vercel-ip-country") ??
    requestHeaders.get("cf-ipcountry");
  const override =
    countryHeader === null && process.env.NODE_ENV === "development"
      ? (await searchParams).country
      : undefined;
  const country = (
    countryHeader ?? (typeof override === "string" ? override : "")
  )
    .trim()
    .toUpperCase();
  return country === "IN" ? PRICE_CONFIG.IN : PRICE_CONFIG.DEFAULT;
}
